import json, uuid
from pathlib import Path
import catalog_round3 as base
ROOT=Path(__file__).resolve().parents[1]
LOCK=json.loads((ROOT/'images.round4.lock.json').read_text())
secret,ref,private,public=base.secret,base.ref,base.private,base.public

def svc(name,**kw):
    # Resolve our own lock explicitly, leaving the released module's globals alone.
    if kw.get('image'):kw['image']=LOCK.get(kw['image'],kw['image'])
    return base.svc(name,**kw)
def pg(app,name='postgres',image='postgres:17'):
    return svc(name,image=image,volume='/var/lib/postgresql/data',env={'POSTGRES_USER':app,'POSTGRES_DB':app,'POSTGRES_PASSWORD':secret(),'PGDATA':'/var/lib/postgresql/data/pgdata','DATABASE_URL':'postgresql://'+app+':'+ref(name,'POSTGRES_PASSWORD')+'@'+ref(name,'RAILWAY_PRIVATE_DOMAIN')+':5432/'+app})
