CATALOG={'fastgpt':fastgpt,'dolt':dolt,'xberg':xberg,'agentscope':agentscope,'coze-studio':coze,'bettafish':bettafish,'openrag':openrag,'marker':marker,'acontext':acontext,'seekdb':seekdb}
def generate():
    for name,factory in CATALOG.items():
        services=factory();config={'services':{str(uuid.uuid5(uuid.NAMESPACE_URL,'round4/'+name+'/'+s['name'])):s for s in services}}
        p=ROOT/'templates'/name;p.mkdir(parents=True,exist_ok=True);(p/'template.json').write_text(json.dumps(config,indent=2)+'\n');print(name,len(services))
if __name__=='__main__':generate()
